SELECT cp.cp_department AS department, d.d_year AS year, d.d_month_seq AS month, w.w_state AS state, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_ext_sales_price) AS total_sales, AVG(cs.cs_ext_discount_amt) AS avg_discount_amt, COUNT(DISTINCT cs.cs_order_number) AS distinct_orders, COUNT(DISTINCT p.p_promo_id) AS distinct_promotions, AVG(inv.inv_quantity_on_hand) AS avg_inventory_on_hand FROM catalog_sales cs JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk LEFT JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk JOIN inventory inv ON inv.inv_date_sk = d.d_date_sk AND inv.inv_warehouse_sk = w.w_warehouse_sk WHERE cp.cp_type = 'quarterly' AND d.d_year = 2001 AND w.w_country = 'United States' GROUP BY cp.cp_department, d.d_year, d.d_month_seq, w.w_state HAVING SUM(cs.cs_net_profit) > 10000 ORDER BY total_net_profit DESC LIMIT 100
